package com.safayet.afsos_nama.repository;

import com.safayet.afsos_nama.model.User;
import org.springframework.data.jpa.repository.JpaRepository;

import java.util.Optional;

import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface UserRepository extends JpaRepository<User, Integer> {

    // Avoid alias-qualified FOR UPDATE OF generated by Hibernate on affected TiDB versions.
    @Query(value = "SELECT * FROM users WHERE id = :id FOR UPDATE", nativeQuery = true)
    Optional<User> findForUpdate(@Param("id") Integer id);

    Optional<User> findByEmail(String email);

    boolean existsByEmail(String email);
}
